using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GeyserUppercutCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/GeyserUppercutCustomDescription", order = 0)]
public class GeyserUppercutCustomDescription : PurifyMinimunWaveCustomDescription
{
	protected override string GetExtraActionDescription(BattleAction battleAction, string amountModified)
	{
		GeyserUppercutAction geyserUppercutAction = battleAction as GeyserUppercutAction;
		return geyserUppercutAction.DrawAction.GetActionDescription(geyserUppercutAction.DrawDiceAmount).RemoveLast().LowercaseFirst();
	}
}
